def parse_json(text: str) -> object:
    n = len(text)
    pos = 0

    def skip_ws():
        nonlocal pos
        while pos < n and text[pos] in ' \t\n\r':
            pos += 1

    def parse_string():
        nonlocal pos
        pos += 1
        chars = []
        while True:
            if pos >= n:
                raise ValueError("unterminated string")
            c = text[pos]
            if c == '"':
                pos += 1
                return ''.join(chars)
            if c == '\\':
                pos += 1
                if pos >= n:
                    raise ValueError("unterminated string")
                esc = text[pos]
                pos += 1
                if esc == '"':
                    chars.append('"')
                elif esc == '\\':
                    chars.append('\\')
                elif esc == '/':
                    chars.append('/')
                elif esc == 'b':
                    chars.append('\b')
                elif esc == 'f':
                    chars.append('\f')
                elif esc == 'n':
                    chars.append('\n')
                elif esc == 'r':
                    chars.append('\r')
                elif esc == 't':
                    chars.append('\t')
                elif esc == 'u':
                    if pos + 4 > n:
                        raise ValueError("invalid escape")
                    h = text[pos:pos + 4]
                    for ch in h:
                        if ch not in '0123456789abcdefABCDEF':
                            raise ValueError("invalid escape")
                    pos += 4
                    code = int(h, 16)
                    if 0xD800 <= code <= 0xDBFF:
                        if pos + 6 > n:
                            raise ValueError("invalid surrogate pair")
                        if text[pos] != '\\' or text[pos + 1] != 'u':
                            raise ValueError("invalid surrogate pair")
                        h2 = text[pos + 2:pos + 6]
                        for ch in h2:
                            if ch not in '0123456789abcdefABCDEF':
                                raise ValueError("invalid surrogate pair")
                        pos += 6
                        low = int(h2, 16)
                        if not (0xDC00 <= low <= 0xDFFF):
                            raise ValueError("invalid surrogate pair")
                        combined = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00)
                        chars.append(chr(combined))
                    elif 0xDC00 <= code <= 0xDFFF:
                        raise ValueError("lone low surrogate")
                    else:
                        chars.append(chr(code))
                else:
                    raise ValueError("invalid escape")
            elif ord(c) < 0x20:
                raise ValueError("control character in string")
            else:
                chars.append(c)
                pos += 1

    def parse_number():
        nonlocal pos
        start = pos
        if pos < n and text[pos] == '-':
            pos += 1
        if pos >= n:
            raise ValueError("invalid number")
        if text[pos] == '0':
            pos += 1
        elif '1' <= text[pos] <= '9':
            while pos < n and '0' <= text[pos] <= '9':
                pos += 1
        else:
            raise ValueError("invalid number")
        is_float = False
        if pos < n and text[pos] == '.':
            pos += 1
            if pos >= n or not ('0' <= text[pos] <= '9'):
                raise ValueError("invalid number")
            while pos < n and '0' <= text[pos] <= '9':
                pos += 1
            is_float = True
        if pos < n and text[pos] in 'eE':
            pos += 1
            if pos < n and text[pos] in '+-':
                pos += 1
            if pos >= n or not ('0' <= text[pos] <= '9'):
                raise ValueError("invalid number")
            while pos < n and '0' <= text[pos] <= '9':
                pos += 1
            is_float = True
        s = text[start:pos]
        if is_float:
            return float(s)
        return int(s)

    state = 'VALUE'
    stack = []
    result = None

    while state != 'DONE':
        if state == 'VALUE':
            skip_ws()
            if pos >= n:
                raise ValueError("unexpected end of input")
            c = text[pos]
            if c == '{':
                pos += 1
                skip_ws()
                if pos < n and text[pos] == '}':
                    pos += 1
                    result = {}
                    state = 'AFTER_VALUE'
                else:
                    stack.append(['obj', {}, None])
                    state = 'OBJ_EXPECT_KEY'
            elif c == '[':
                pos += 1
                skip_ws()
                if pos < n and text[pos] == ']':
                    pos += 1
                    result = []
                    state = 'AFTER_VALUE'
                else:
                    stack.append(['arr', [], None])
                    state = 'ARR_EXPECT_VALUE'
            elif c == '"':
                result = parse_string()
                state = 'AFTER_VALUE'
            elif c == 't':
                if text[pos:pos + 4] == 'true':
                    pos += 4
                    result = True
                    state = 'AFTER_VALUE'
                else:
                    raise ValueError("invalid literal")
            elif c == 'f':
                if text[pos:pos + 5] == 'false':
                    pos += 5
                    result = False
                    state = 'AFTER_VALUE'
                else:
                    raise ValueError("invalid literal")
            elif c == 'n':
                if text[pos:pos + 4] == 'null':
                    pos += 4
                    result = None
                    state = 'AFTER_VALUE'
                else:
                    raise ValueError("invalid literal")
            elif c == '-' or '0' <= c <= '9':
                result = parse_number()
                state = 'AFTER_VALUE'
            else:
                raise ValueError("unexpected character")

        elif state == 'AFTER_VALUE':
            if not stack:
                state = 'TRAILING'
            else:
                top = stack[-1]
                if top[0] == 'obj':
                    top[1][top[2]] = result
                    top[2] = None
                    state = 'OBJ_COMMA'
                else:
                    top[1].append(result)
                    state = 'ARR_COMMA'

        elif state == 'OBJ_EXPECT_KEY':
            skip_ws()
            if pos >= n:
                raise ValueError("unexpected end of input")
            if text[pos] == '"':
                key = parse_string()
                if key in stack[-1][1]:
                    raise ValueError("duplicate key")
                stack[-1][2] = key
                state = 'OBJ_COLON'
            else:
                raise ValueError("expected key")

        elif state == 'OBJ_COLON':
            skip_ws()
            if pos >= n or text[pos] != ':':
                raise ValueError("expected colon")
            pos += 1
            state = 'VALUE'

        elif state == 'OBJ_COMMA':
            skip_ws()
            if pos >= n:
                raise ValueError("unexpected end of input")
            if text[pos] == ',':
                pos += 1
                state = 'OBJ_EXPECT_KEY'
            elif text[pos] == '}':
                pos += 1
                result = stack[-1][1]
                stack.pop()
                state = 'AFTER_VALUE'
            else:
                raise ValueError("expected comma or closing brace")

        elif state == 'ARR_EXPECT_VALUE':
            state = 'VALUE'

        elif state == 'ARR_COMMA':
            skip_ws()
            if pos >= n:
                raise ValueError("unexpected end of input")
            if text[pos] == ',':
                pos += 1
                state = 'ARR_EXPECT_VALUE'
            elif text[pos] == ']':
                pos += 1
                result = stack[-1][1]
                stack.pop()
                state = 'AFTER_VALUE'
            else:
                raise ValueError("expected comma or closing bracket")

        elif state == 'TRAILING':
            skip_ws()
            if pos != n:
                raise ValueError("trailing characters")
            state = 'DONE'

    return result
